:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --ink: #1f2933;
  --muted: #6b7280;
  --border: #e2e5ea;
  --accent: #2563eb;
  --accent-ink: #ffffff;
  --danger: #dc2626;
  --warn-bg: #fef3c7;
  --warn-ink: #92400e;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 3rem;
}

.app__header { text-align: center; margin-bottom: 1.5rem; }
.app__header h1 { margin: 0; font-size: 1.7rem; }
.app__subtitle { margin: 0.25rem 0 0; color: var(--muted); }

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

.card__title { margin: 0 0 0.75rem; font-size: 1.1rem; }

.form { display: grid; gap: 0.75rem; }
.form__field { display: grid; gap: 0.25rem; font-size: 0.9rem; }
.form__field span { color: var(--muted); }
.required { color: var(--danger); }

input, textarea, select {
  width: 100%;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font: inherit;
  color: inherit;
  background: #fff;
}
input:focus, textarea:focus, select:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-color: var(--accent);
}
textarea { resize: vertical; }

.form__actions { display: flex; gap: 0.5rem; }

.btn {
  padding: 0.55rem 1rem;
  border-radius: 8px;
  border: 1px solid transparent;
  font: inherit;
  cursor: pointer;
}
.btn--primary { background: var(--accent); color: var(--accent-ink); }
.btn--primary:hover { filter: brightness(0.95); }
.btn--ghost { background: transparent; border-color: var(--border); color: var(--ink); }
.btn--link {
  background: none; border: none; cursor: pointer; padding: 0;
  color: var(--accent); font: inherit; text-decoration: underline;
}
.btn--danger { color: var(--danger); }

.form__message { margin: 0; min-height: 1.2em; font-size: 0.9rem; }
.form__message--error { color: var(--danger); }
.form__message--warn {
  color: var(--warn-ink); background: var(--warn-bg);
  padding: 0.5rem 0.65rem; border-radius: 8px;
}
.form__message--success { color: #15803d; }

.toolbar {
  display: flex; flex-wrap: wrap; gap: 0.75rem;
  align-items: center; justify-content: space-between; margin-bottom: 0.5rem;
}
.toolbar__filters { display: flex; gap: 0.5rem; flex: 1 1 320px; }
.toolbar__filters #search { flex: 2; }
.toolbar__filters #tag-filter { flex: 1; min-width: 110px; }

.list-status { color: var(--muted); margin: 0.5rem 0; }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.6rem; }

.bookmark {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 0.85rem;
  display: grid;
  gap: 0.35rem;
}
.bookmark__title {
  font-weight: 600; font-size: 1rem;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bookmark__title a { color: var(--accent); text-decoration: none; }
